import { jest } from '@jest/globals';
describe('generateAIResponse', () => {
    it('calls OpenAI with configured API key and model', async () => {
        const fetchMock = jest.fn().mockResolvedValue({
            ok: true,
            json: async () => ({ choices: [{ message: { content: 'hello' } }] })
        });
        global.fetch = fetchMock;
        const readConfig = jest.fn().mockReturnValue({
            aiProvider: 'openai',
            aiModel: 'gpt-3.5-turbo',
            tokens: { openai: 'test-key' }
        });
        jest.unstable_mockModule('../src/utils/config.js', () => ({ readConfig }));
        const { generateAIResponse } = await import('../src/ai/provider.js');
        const result = await generateAIResponse('say hi', 'casual');
        expect(result).toBe('hello');
        expect(fetchMock).toHaveBeenCalled();
        const [url, options] = fetchMock.mock.calls[0];
        expect(String(url)).toMatch(/chat\/completions/);
        expect(options.headers.Authorization).toBe('Bearer test-key');
    });
    it('returns fallback when API fails', async () => {
        const fetchMock = jest.fn().mockResolvedValue({ ok: false, status: 500, text: async () => 'err' });
        global.fetch = fetchMock;
        const readConfig = jest.fn().mockReturnValue({ tokens: { openai: 'key' } });
        jest.unstable_mockModule('../src/utils/config.js', () => ({ readConfig }));
        const { generateAIResponse } = await import('../src/ai/provider.js');
        const result = await generateAIResponse('test prompt', 'emoji');
        expect(result).toContain('[AI unavailable]');
    });
});
